// ServerInterface represents all server handlers.
type ServerInterface interface {
	// ListAccounts The eToro accounts you own or were given, with your access
	// (GET /api/v1/accounts)
	ListAccounts(w http.ResponseWriter, r *http.Request)
	// CreateAccount Add an eToro account you own (operator or admin)
	// (POST /api/v1/accounts)
	CreateAccount(w http.ResponseWriter, r *http.Request)
	// SetCurrentAccount Switch the account you are working on
	// (PUT /api/v1/accounts/current)
	SetCurrentAccount(w http.ResponseWriter, r *http.Request)
	// DeleteAccount Delete an account, its keys, shares and watchlist (owner, web UI)
	// (DELETE /api/v1/accounts/{accountId})
	DeleteAccount(w http.ResponseWriter, r *http.Request, accountId string)
	// RenameAccount Rename an account (owner)
	// (PATCH /api/v1/accounts/{accountId})
	RenameAccount(w http.ResponseWriter, r *http.Request, accountId string)
	// GetAccountKeys Whether the account's eToro keys are set (never their values)
	// (GET /api/v1/accounts/{accountId}/keys)
	GetAccountKeys(w http.ResponseWriter, r *http.Request, accountId string)
	// SetAccountKeys Store the account's eToro key pair, write-only (owner, web UI); an empty value keeps the stored one
	// (PUT /api/v1/accounts/{accountId}/keys)
	SetAccountKeys(w http.ResponseWriter, r *http.Request, accountId string)
	// ListAccountShares Who the account is shared with (owner)
	// (GET /api/v1/accounts/{accountId}/shares)
	ListAccountShares(w http.ResponseWriter, r *http.Request, accountId string)
	// ShareAccount Give a user view or trade access (owner, web UI)
	// (PUT /api/v1/accounts/{accountId}/shares)
	ShareAccount(w http.ResponseWriter, r *http.Request, accountId string)
	// UnshareAccount Remove a user's access (owner, web UI)
	// (DELETE /api/v1/accounts/{accountId}/shares/{userId})
	UnshareAccount(w http.ResponseWriter, r *http.Request, accountId string, userId string)
	// TestAccount Test the account's eToro connection (owner; one read-only call)
	// (POST /api/v1/accounts/{accountId}/test)
	TestAccount(w http.ResponseWriter, r *http.Request, accountId string)
	// ListApiKeys List your API keys (admins see all)
	// (GET /api/v1/api-keys)
	ListApiKeys(w http.ResponseWriter, r *http.Request)
	// CreateApiKey Create an API key (signed-in users only; role ≤ yours)
	// (POST /api/v1/api-keys)
	CreateApiKey(w http.ResponseWriter, r *http.Request)
	// RevokeApiKey Revoke an API key (yours; admins any)
	// (DELETE /api/v1/api-keys/{keyId})
	RevokeApiKey(w http.ResponseWriter, r *http.Request, keyId string)
	// ListAudit Newest audit entries (admin)
	// (GET /api/v1/audit)
	ListAudit(w http.ResponseWriter, r *http.Request, params ListAuditParams)
	// Login Sign in (sets the session cookie)
	// (POST /api/v1/auth/login)
	Login(w http.ResponseWriter, r *http.Request)
	// Logout Sign out (clears the session cookie)
	// (POST /api/v1/auth/logout)
	Logout(w http.ResponseWriter, r *http.Request)
	// GetMe The signed-in user, permissions and CSRF token
	// (GET /api/v1/auth/me)
	GetMe(w http.ResponseWriter, r *http.Request)
	// ChangePassword Change your own password (ends your other sessions)
	// (POST /api/v1/auth/password)
	ChangePassword(w http.ResponseWriter, r *http.Request)
	// GetPortfolio The eToro account now — cash, positions, pending orders (viewer)
	// (GET /api/v1/broker/portfolio)
	GetPortfolio(w http.ResponseWriter, r *http.Request)
	// TestBrokerConnection Test the eToro connection with the current mode's keys (admin; one read-only call)
	// (POST /api/v1/broker/test)
	TestBrokerConnection(w http.ResponseWriter, r *http.Request)
	// ListCredentials Which credentials are set (never their values)
	// (GET /api/v1/credentials)
	ListCredentials(w http.ResponseWriter, r *http.Request)
	// DeleteCredential Delete a credential (admin, web UI session only)
	// (DELETE /api/v1/credentials/{name})
	DeleteCredential(w http.ResponseWriter, r *http.Request, name CredentialName)
	// SetCredential Set a credential (admin, web UI session only); write-only
	// (PUT /api/v1/credentials/{name})
	SetCredential(w http.ResponseWriter, r *http.Request, name CredentialName)
	// ListEvents The newest events and the caller's unread count (viewer)
	// (GET /api/v1/events)
	ListEvents(w http.ResponseWriter, r *http.Request, params ListEventsParams)
	// MarkEventsSeen Mark every event as seen by the caller
	// (POST /api/v1/events/seen)
	MarkEventsSeen(w http.ResponseWriter, r *http.Request)
	// ListIndustries eToro's stock industries (view)
	// (GET /api/v1/industries)
	ListIndustries(w http.ResponseWriter, r *http.Request)
	// SearchInstruments Search eToro instruments by name or symbol (admin)
	// (GET /api/v1/instruments/search)
	SearchInstruments(w http.ResponseWriter, r *http.Request, params SearchInstrumentsParams)
	// GetLlmSetup The LLM reviewer's setup and the providers to choose from (viewer; never the key)
	// (GET /api/v1/llm)
	GetLlmSetup(w http.ResponseWriter, r *http.Request)
	// SetLlmConfig Change the LLM reviewer's setup (admin, web UI). The API key is set on the credentials endpoint (llm_api_key).
	// (PUT /api/v1/llm)
	SetLlmConfig(w http.ResponseWriter, r *http.Request)
	// ListLlmModels List the models a provider offers with the stored key (admin)
	// (POST /api/v1/llm/models)
	ListLlmModels(w http.ResponseWriter, r *http.Request)
	// TestLlm Ask the reviewer about a made-up trade (admin; nothing is traded)
	// (POST /api/v1/llm/test)
	TestLlm(w http.ResponseWriter, r *http.Request)
	// GetMarketStatus Today's sessions for LSE and NYSE/NASDAQ (viewer)
	// (GET /api/v1/market/status)
	GetMarketStatus(w http.ResponseWriter, r *http.Request)
	// GetPublicStatus What the sign-in page needs before anyone is signed in
	// (GET /api/v1/public/status)
	GetPublicStatus(w http.ResponseWriter, r *http.Request)
	// ListReviews The stocks the scanner reviewed for the current account, the rules applied and the outcome (view)
	// (GET /api/v1/reviews)
	ListReviews(w http.ResponseWriter, r *http.Request, params ListReviewsParams)
	// GetRiskLimits The risk limits (viewer)
	// (GET /api/v1/risk/limits)
	GetRiskLimits(w http.ResponseWriter, r *http.Request)
	// SetRiskLimits Change the risk limits (admin, web UI, only while the agent is stopped)
	// (PUT /api/v1/risk/limits)
	SetRiskLimits(w http.ResponseWriter, r *http.Request)
	// SetScanner Switch the scanner on or off for the current account (trade access)
	// (PUT /api/v1/scanner)
	SetScanner(w http.ResponseWriter, r *http.Request)
	// RunScanner Review the current account's themes and watchlist now (trade access; read-only on eToro)
	// (POST /api/v1/scanner/run)
	RunScanner(w http.ResponseWriter, r *http.Request)
	// ReloadSettings Re-read credentials from the environment and secret files (admin, web UI)
	// (POST /api/v1/system/reload)
	ReloadSettings(w http.ResponseWriter, r *http.Request)
	// RestartServer Restart cactusTrade gracefully (admin, web UI)
	// (POST /api/v1/system/restart)
	RestartServer(w http.ResponseWriter, r *http.Request)
	// GetSystemStatus Version, trading mode and agent state (viewer)
	// (GET /api/v1/system/status)
	GetSystemStatus(w http.ResponseWriter, r *http.Request)
	// ListThemes The current account's themes (view)
	// (GET /api/v1/themes)
	ListThemes(w http.ResponseWriter, r *http.Request)
	// CreateTheme Add a theme such as Space or Semiconductors (trade access)
	// (POST /api/v1/themes)
	CreateTheme(w http.ResponseWriter, r *http.Request)
	// DeleteTheme Remove a theme (trade access)
	// (DELETE /api/v1/themes/{themeId})
	DeleteTheme(w http.ResponseWriter, r *http.Request, themeId string)
	// UpdateTheme Change a theme (trade access)
	// (PUT /api/v1/themes/{themeId})
	UpdateTheme(w http.ResponseWriter, r *http.Request, themeId string)
	// ListUsers List users (admin)
	// (GET /api/v1/users)
	ListUsers(w http.ResponseWriter, r *http.Request)
	// CreateUser Create a user (admin)
	// (POST /api/v1/users)
	CreateUser(w http.ResponseWriter, r *http.Request)
	// DeleteUser Delete a user, their sessions and API keys (admin)
	// (DELETE /api/v1/users/{userId})
	DeleteUser(w http.ResponseWriter, r *http.Request, userId string)
	// UpdateUser Change a user's role, enabled state or password (admin)
	// (PATCH /api/v1/users/{userId})
	UpdateUser(w http.ResponseWriter, r *http.Request, userId string)
	// ListWatchlist The instruments the agent may trade (viewer)
	// (GET /api/v1/watchlist)
	ListWatchlist(w http.ResponseWriter, r *http.Request)
	// AddToWatchlist Add a share after eToro confirms it can be bought as a real share at leverage 1 (admin)
	// (POST /api/v1/watchlist)
	AddToWatchlist(w http.ResponseWriter, r *http.Request)
	// ListWatchlistQuotes Current bid/ask of the watchlist (viewer)
	// (GET /api/v1/watchlist/quotes)
	ListWatchlistQuotes(w http.ResponseWriter, r *http.Request)
	// RemoveFromWatchlist Remove an instrument (admin)
	// (DELETE /api/v1/watchlist/{instrumentId})
	RemoveFromWatchlist(w http.ResponseWriter, r *http.Request, instrumentId int64)
	// Healthz Liveness (the process is serving)
	// (GET /healthz)
	Healthz(w http.ResponseWriter, r *http.Request)
	// Readyz Readiness (the database answers)
	// (GET /readyz)
	Readyz(w http.ResponseWriter, r *http.Request)
}

